// The Bookkeeping pack's tables (docs/plan.md §1.79, B-1): the bank feed's accounts linked to the
// client's chart of accounts, the transactions read from the feed, the client's rules and the
// bookings proposed for each transaction. Same tenancy rules as the platform's (CLAUDE.md
// invariant 1): every table has tenant_id, forced RLS on app.tenant_ids, and composite foreign keys
// (id, tenant_id) so a row can only point at the same client's rows.
//
// Migration 0039 creates them (generated by drizzle-kit from this file, which the db package's
// drizzle config lists, plus hand-written SQL for the grants, RLS, the partial unique index and the
// pack comments). This file imports only drizzle-orm and the platform's schema at runtime, so
// drizzle-kit can load it.

import {
  agentVersion,
  appUser,
  connection,
  externalAction,
  ledgerAccount,
  rawRecord,
  run,
  tenant,
  transaction,
  vendor,
} from "@countersign/db";
import { type SQL, sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// ── Allowed values ───────────────────────────────────────────────────────────────────────────────

export const LINK_KINDS = ["bank", "card", "other"] as const;
export type LinkKind = (typeof LINK_KINDS)[number];
/** `off`: not booked; `suggest`: proposed only; `book`: proposed, then written once approved. */
export const LINK_MODES = ["off", "suggest", "book"] as const;
export type LinkMode = (typeof LINK_MODES)[number];
export const DIRECTIONS = ["in", "out"] as const;
export type Direction = (typeof DIRECTIONS)[number];
export const BANK_TXN_STATUSES = [
  "pending",
  "new",
  "matched",
  "proposed",
  "needs_review",
  "approved",
  "posted",
  "excluded",
  "removed",
  "skipped",
] as const;
export type BankTxnStatus = (typeof BANK_TXN_STATUSES)[number];
export const RULE_SOURCES = ["person", "learned"] as const;
export type RuleSource = (typeof RULE_SOURCES)[number];
export const BOOKING_KINDS = ["expense", "deposit", "transfer", "match"] as const;
export type BookingKind = (typeof BOOKING_KINDS)[number];
export const BOOKING_STATUSES = [
  "proposed",
  "approved",
  "rejected",
  "posted",
  "failed",
  "superseded",
] as const;
export type BookingStatus = (typeof BOOKING_STATUSES)[number];
/** A booking that still stands: at most one per transaction. */
export const LIVE_BOOKING_STATUSES = ["proposed", "approved", "posted"] as const;
export const DECIDED_BY = ["match", "rule", "model", "person"] as const;
export type DecidedBy = (typeof DECIDED_BY)[number];

function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

const id = () => uuid("id").primaryKey().default(sql`uuid_generate_v7()`);
const tenantId = () =>
  uuid("tenant_id")
    .notNull()
    .references(() => tenant.id);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();
const ts = (name: string) => timestamp(name, { withTimezone: true });
const money = (name: string) => numeric(name, { precision: 14, scale: 4 });

// ── Tables ───────────────────────────────────────────────────────────────────────────────────────

/** One bank or card account seen in a client's bank feed, and the ledger account it books to. */
export const bankAccountLink = pgTable(
  "bank_account_link",
  {
    id: id(),
    tenantId: tenantId(),
    connectionId: uuid("connection_id").notNull(),
    /** The feed's own id for the account (Plaid's account_id). */
    externalAccountId: text("external_account_id").notNull(),
    name: text("name"),
    mask: text("mask"),
    kind: text("kind").$type<LinkKind>().notNull(),
    /** The client's bank or card account in its accounting tool; null until a person links it. */
    ledgerAccountId: uuid("ledger_account_id"),
    mode: text("mode").$type<LinkMode>().notNull().default("off"),
    /** Transactions dated before this aren't booked. */
    bookFrom: date("book_from"),
    updatedBy: uuid("updated_by").references(() => appUser.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("bank_account_link_id_tenant_key").on(t.id, t.tenantId),
    unique("bank_account_link_account_key").on(t.tenantId, t.connectionId, t.externalAccountId),
    foreignKey({
      name: "bank_account_link_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
    foreignKey({
      name: "bank_account_link_ledger_account_fk",
      columns: [t.ledgerAccountId, t.tenantId],
      foreignColumns: [ledgerAccount.id, ledgerAccount.tenantId],
    }),
    check("bank_account_link_kind_check", oneOf(t.kind, LINK_KINDS)),
    check("bank_account_link_mode_check", oneOf(t.mode, LINK_MODES)),
    // A link that books names the account it books to.
    check("bank_account_link_on_check", sql`${t.mode} = 'off' or ${t.ledgerAccountId} is not null`),
  ],
);

/** Where the import got to in one feed's raw records. */
export const bankFeedCursor = pgTable(
  "bank_feed_cursor",
  {
    tenantId: tenantId(),
    connectionId: uuid("connection_id").notNull(),
    lastRawRecordId: uuid("last_raw_record_id").notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({ name: "bank_feed_cursor_pkey", columns: [t.tenantId, t.connectionId] }),
    foreignKey({
      name: "bank_feed_cursor_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
  ],
);

/** One bank or card transaction from the feed, at its latest version. */
export const bankTxn = pgTable(
  "bank_txn",
  {
    id: id(),
    tenantId: tenantId(),
    connectionId: uuid("connection_id").notNull(),
    accountLinkId: uuid("account_link_id").notNull(),
    /** The feed's own id (Plaid's transaction_id). */
    externalId: text("external_id").notNull(),
    /** The raw record of the latest version read. */
    rawRecordId: uuid("raw_record_id").notNull(),
    txnDate: date("txn_date").notNull(),
    /** Always positive; `direction` says which way. */
    amount: money("amount").notNull(),
    currency: text("currency").notNull().default("USD"),
    direction: text("direction").$type<Direction>().notNull(),
    /** The merchant's name, else the bank's words. */
    payee: text("payee"),
    /** `payee` normalised: what rules match on. */
    payeeKey: text("payee_key"),
    description: text("description"),
    bankCategory: text("bank_category"),
    status: text("status").$type<BankTxnStatus>().notNull().default("new"),
    /** e.g. `removedAfterPosting`. */
    ext: jsonb("ext").$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("bank_txn_id_tenant_key").on(t.id, t.tenantId),
    unique("bank_txn_external_key").on(t.tenantId, t.connectionId, t.externalId),
    foreignKey({
      name: "bank_txn_connection_fk",
      columns: [t.connectionId, t.tenantId],
      foreignColumns: [connection.id, connection.tenantId],
    }),
    foreignKey({
      name: "bank_txn_account_link_fk",
      columns: [t.accountLinkId, t.tenantId],
      foreignColumns: [bankAccountLink.id, bankAccountLink.tenantId],
    }),
    foreignKey({
      name: "bank_txn_raw_record_fk",
      columns: [t.rawRecordId, t.tenantId],
      foreignColumns: [rawRecord.id, rawRecord.tenantId],
    }),
    index("bank_txn_status_idx").on(t.tenantId, t.status, t.txnDate),
    index("bank_txn_link_idx").on(t.tenantId, t.accountLinkId, t.txnDate),
    check("bank_txn_direction_check", oneOf(t.direction, DIRECTIONS)),
    check("bank_txn_status_check", oneOf(t.status, BANK_TXN_STATUSES)),
    check("bank_txn_amount_check", sql`${t.amount} >= 0`),
  ],
);

/** The client's rule for a payee: which account (and vendor, class, memo) it books to. */
export const bookingRule = pgTable(
  "booking_rule",
  {
    id: id(),
    tenantId: tenantId(),
    payeeKey: text("payee_key").notNull(),
    direction: text("direction").$type<Direction>().notNull(),
    /** Null: on any linked account. */
    accountLinkId: uuid("account_link_id"),
    ledgerAccountId: uuid("ledger_account_id").notNull(),
    vendorId: uuid("vendor_id"),
    /** The class's id in the accounting tool. */
    classRef: text("class_ref"),
    memo: text("memo"),
    source: text("source").$type<RuleSource>().notNull(),
    active: boolean("active").notNull().default(true),
    hits: integer("hits").notNull().default(0),
    createdBy: uuid("created_by").references(() => appUser.id),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("booking_rule_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "booking_rule_account_link_fk",
      columns: [t.accountLinkId, t.tenantId],
      foreignColumns: [bankAccountLink.id, bankAccountLink.tenantId],
    }),
    foreignKey({
      name: "booking_rule_ledger_account_fk",
      columns: [t.ledgerAccountId, t.tenantId],
      foreignColumns: [ledgerAccount.id, ledgerAccount.tenantId],
    }),
    foreignKey({
      name: "booking_rule_vendor_fk",
      columns: [t.vendorId, t.tenantId],
      foreignColumns: [vendor.id, vendor.tenantId],
    }),
    index("booking_rule_payee_idx").on(t.tenantId, t.payeeKey, t.direction),
    check("booking_rule_direction_check", oneOf(t.direction, DIRECTIONS)),
    check("booking_rule_source_check", oneOf(t.source, RULE_SOURCES)),
  ],
);

/**
 * How one transaction is booked, as proposed and then decided. Inserted, then only its status
 * columns change; a changed decision is a new booking and the old one `superseded`.
 */
export const booking = pgTable(
  "booking",
  {
    id: id(),
    tenantId: tenantId(),
    bankTxnId: uuid("bank_txn_id").notNull(),
    kind: text("kind").$type<BookingKind>().notNull(),
    status: text("status").$type<BookingStatus>().notNull().default("proposed"),
    decidedBy: text("decided_by").$type<DecidedBy>().notNull(),
    confidence: numeric("confidence", { precision: 4, scale: 3 }).notNull(),
    ruleId: uuid("rule_id"),
    /** A record already in the accounting tool that this transaction is (kind `match`). */
    matchedTransactionId: uuid("matched_transaction_id"),
    /** For a transfer between two accounts on the feed: the other one's link. */
    transferLinkId: uuid("transfer_link_id"),
    vendorId: uuid("vendor_id"),
    memo: text("memo"),
    /** Why it was decided so, in a sentence (a model's or a person's). */
    reason: text("reason"),
    /** Other accounts the decider weighed (ledger_account ids), for the card and the questions. */
    alternatives: jsonb("alternatives").$type<string[]>().notNull().default([]),
    sources: jsonb("sources").$type<string[]>().notNull().default([]),
    agentVersionId: uuid("agent_version_id").references(() => agentVersion.id),
    runId: uuid("run_id"),
    /** The person who decided it or approved it. */
    userId: uuid("user_id").references(() => appUser.id),
    externalActionId: uuid("external_action_id"),
    /** What it became in the accounting tool, e.g. `Purchase` and its id. */
    qboEntity: text("qbo_entity"),
    qboId: text("qbo_id"),
    error: text("error"),
    createdAt: createdAt(),
    decidedAt: ts("decided_at"),
    postedAt: ts("posted_at"),
  },
  (t) => [
    unique("booking_id_tenant_key").on(t.id, t.tenantId),
    foreignKey({
      name: "booking_bank_txn_fk",
      columns: [t.bankTxnId, t.tenantId],
      foreignColumns: [bankTxn.id, bankTxn.tenantId],
    }),
    foreignKey({
      name: "booking_rule_fk",
      columns: [t.ruleId, t.tenantId],
      foreignColumns: [bookingRule.id, bookingRule.tenantId],
    }),
    foreignKey({
      name: "booking_matched_transaction_fk",
      columns: [t.matchedTransactionId, t.tenantId],
      foreignColumns: [transaction.id, transaction.tenantId],
    }),
    foreignKey({
      name: "booking_transfer_link_fk",
      columns: [t.transferLinkId, t.tenantId],
      foreignColumns: [bankAccountLink.id, bankAccountLink.tenantId],
    }),
    foreignKey({
      name: "booking_vendor_fk",
      columns: [t.vendorId, t.tenantId],
      foreignColumns: [vendor.id, vendor.tenantId],
    }),
    foreignKey({
      name: "booking_run_fk",
      columns: [t.runId, t.tenantId],
      foreignColumns: [run.id, run.tenantId],
    }),
    foreignKey({
      name: "booking_external_action_fk",
      columns: [t.externalActionId, t.tenantId],
      foreignColumns: [externalAction.id, externalAction.tenantId],
    }),
    // DECISION: one live booking per transaction, kept by the database (docs/plan.md §1.79).
    uniqueIndex("booking_live_key")
      .on(t.tenantId, t.bankTxnId)
      .where(sql`${t.status} in ('proposed', 'approved', 'posted')`),
    index("booking_status_idx").on(t.tenantId, t.status),
    check("booking_kind_check", oneOf(t.kind, BOOKING_KINDS)),
    check("booking_status_check", oneOf(t.status, BOOKING_STATUSES)),
    check("booking_decided_by_check", oneOf(t.decidedBy, DECIDED_BY)),
    check("booking_confidence_check", sql`${t.confidence} between 0 and 1`),
    check(
      "booking_match_check",
      sql`(${t.kind} = 'match') = (${t.matchedTransactionId} is not null)`,
    ),
    check(
      "booking_transfer_check",
      sql`${t.transferLinkId} is null or ${t.kind} = 'transfer'`,
    ),
    // Invariant 10: a model's or a rule's decision names the agent version that made it.
    check(
      "booking_decider_check",
      sql`${t.decidedBy} = 'person' and ${t.userId} is not null or ${t.decidedBy} <> 'person' and ${t.agentVersionId} is not null`,
    ),
  ],
);

/** A booking's lines: which accounts the amount goes to. They add up to the transaction's amount. */
export const bookingLine = pgTable(
  "booking_line",
  {
    id: id(),
    tenantId: tenantId(),
    bookingId: uuid("booking_id").notNull(),
    lineNo: integer("line_no").notNull(),
    ledgerAccountId: uuid("ledger_account_id").notNull(),
    amount: money("amount").notNull(),
    classRef: text("class_ref"),
    customerRef: text("customer_ref"),
    description: text("description"),
  },
  (t) => [
    unique("booking_line_no_key").on(t.bookingId, t.lineNo),
    foreignKey({
      name: "booking_line_booking_fk",
      columns: [t.bookingId, t.tenantId],
      foreignColumns: [booking.id, booking.tenantId],
    }),
    foreignKey({
      name: "booking_line_ledger_account_fk",
      columns: [t.ledgerAccountId, t.tenantId],
      foreignColumns: [ledgerAccount.id, ledgerAccount.tenantId],
    }),
    index("booking_line_account_idx").on(t.tenantId, t.ledgerAccountId),
    check("booking_line_amount_check", sql`${t.amount} > 0`),
  ],
);

/** The pack's tables, for the migration's grants and RLS and the tests. */
export const BOOKKEEPING_TABLES = [
  "bank_account_link",
  "bank_feed_cursor",
  "bank_txn",
  "booking_rule",
  "booking",
  "booking_line",
] as const;
